def fit_rat(X, F, tr, te, Y, mode):
    from scipy.optimize import least_squares
    W = X * X
    if mode in (1, 3):
        W = np.c_[W, cross(X, X)[:, [1, 2, 3, 6, 7, 11]]]

    def pred(p, tgt):
        if mode in (1, 3):
            L = np.array([[p[0], 0, 0, 0], [p[4], p[1], 0, 0], [p[5], p[7], p[2], 0], [p[6], p[8], p[9], p[3]]])
            D = 1 + np.sum((X @ L) ** 2, axis=1)
        else:
            D = 1 + W @ p
        D = F / D[:, None]
        M = D if mode < 2 else np.c_[D, poly(X, 2)]
        R = M[tr]
        c = fit(R, Y[tr]) if mode < 2 else np.linalg.solve(R.T @ R + 0.0003 * np.eye(R.shape[1]), R.T @ Y[tr])
        return M[tgt] @ c
    init = np.r_[np.full(4, 0.4), np.zeros(6)] if mode in (1, 3) else np.full(4, 0.2)
    p = least_squares(lambda p: pred(p, tr) - Y[tr], init, bounds=(0, 5) if mode in (0, 2) else (-3, 3), max_nfev=35).x
    return pred(p, te)
